from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = next(r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg)
    marker_color = grid[marker][0]
    object_colors = {v for row in grid for v in row if v not in (bg, marker_color)}
    object_rows = [r for r, row in enumerate(grid) if any(v in object_colors for v in row)]
    if not object_rows:
        return [row[:] for row in grid]
    top, bottom = min(object_rows), max(object_rows)
    out = [row[:] for row in grid]
    # The figure drops one row toward the horizontal barrier if there is room.
    if bottom + 1 < marker:
        for r in range(bottom, top - 1, -1):
            out[r + 1] = grid[r][:]
        out[top] = [8] * w
    return out", "exit_code": 0, "error": null}
